#include <stdio.h>
#include <string.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/time.h>

int main() {
    int listen_sock = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in serv;
    serv.sin_family = AF_INET;
    serv.sin_port = htons(6000);
    serv.sin_addr.s_addr = INADDR_ANY;
    bind(listen_sock, (struct sockaddr *)&serv, sizeof(serv));
    listen(listen_sock, 1);
    struct sockaddr_in client;
    socklen_t cl_len = sizeof(client);
    int conn_sock = accept(listen_sock, (struct sockaddr *)&client, &cl_len);
    /* Set a receive timeout so the program does not block forever */
    struct timeval tv; tv.tv_sec = 2; tv.tv_usec = 0;
    setsockopt(conn_sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    char buf[64];
    ssize_t n = recv(conn_sock, buf, sizeof(buf)-1, 0);
    if (n > 0) buf[n] = '\0'; else buf[0] = '\0';
    printf("Server received: %s\n", buf);
    const char *reply = "ACK";
    send(conn_sock, reply, strlen(reply), 0);
    close(conn_sock);
    close(listen_sock);
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/time.h>

int main() {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    /* Bind to a local port so we can receive the reply */
    struct sockaddr_in local;
    local.sin_family = AF_INET;
    local.sin_port = htons(5000);
    local.sin_addr.s_addr = INADDR_ANY;
    bind(sock, (struct sockaddr *)&local, sizeof(local));
    /* Set a timeout to avoid blocking forever */
    struct timeval tv; tv.tv_sec = 2; tv.tv_usec = 0;
    setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    struct sockaddr_in serv;
    serv.sin_family = AF_INET;
    serv.sin_port = htons(5000);
    serv.sin_addr.s_addr = inet_addr("127.0.0.1");
    const char *msg = "Hi";
    sendto(sock, msg, strlen(msg), 0, (struct sockaddr *)&serv, sizeof(serv));
    char buf[64];
    struct sockaddr_in from;
    socklen_t fromlen = sizeof(from);
    ssize_t n = recvfrom(sock, buf, sizeof(buf)-1, 0, (struct sockaddr *)&from, &fromlen);
    if (n > 0) buf[n] = '\0'; else buf[0] = '\0';
    printf("Received: %s\n", buf);
    close(sock);
    return 0;
}

